            aCross = RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 29047U)) & S_BLOCK1], 29U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 29362U)) & S_BLOCK1], 10U);
