            aOrbiterK = ((aWandererD + RotL64(aPrevious, 13U)) + 0xA404DC7E34F7A6A4ULL) + aOASaltA[(((511U - aIndex) + 55U)) & S_SALT1];
            aOrbiterE = ((aWandererK + RotL64(aCross, 51U)) + RotL64(aCarry, 53U)) + 0x4057959336404174ULL;
            aOrbiterG = (aWandererJ + RotL64(aIngress, 29U)) + 0x518CF783F6470393ULL;
