            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0xD9909958A0ABE15DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x1C5F7AAB336C5258ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xF511D2B127CBA3B7ULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x817B6422DCD6B0B2ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x18B98B6C588DED56ULL) ^ aOUSaltB[((aIndex + 41U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xCD1E5FA90DAE346DULL), 47U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xD6EF6ABA631D78CFULL) + aOUSaltD[(((511U - aIndex) + 401U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x27505CA4BC353F93ULL;
