            aOrbiterA = (((aWandererE + RotL64(aIngress, 47U)) + RotL64(aCarry, 21U)) + 0xF56486EFC778C39CULL) + aOASaltH[((aIndex + 231U)) & S_SALT1];
            aOrbiterJ = ((aWandererK + RotL64(aCross, 37U)) + RotL64(aCarry, 5U)) + 0x9376CCD136514A3FULL;
            aOrbiterG = (aWandererB + RotL64(aPrevious, 21U)) + 0x4DC059659F6A83E8ULL;
            aOrbiterB = ((aWandererI + RotL64(aCross, 28U)) + 0x1CEF026A9C571519ULL) + aOASaltG[((aIndex + 394U)) & S_SALT1];
            aOrbiterK = ((aWandererH + RotL64(aScatter, 13U)) + RotL64(aCarry, 41U)) + 0x3E5E5C486324A890ULL;
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x8CDEEF66DB36FE92ULL) + aOUSaltB[(((511U - aIndex) + 80U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x7E1C08336CD42D08ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x767D0A64CB65BA8FULL), 41U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x10447E7E45AC7551ULL) + aOUSaltC[((aIndex + 425U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0xE520F5018AB24F3BULL) ^ aOUSaltF[(((511U - aIndex) + 219U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xFD3047C6467A7215ULL), 3U);
