            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 11539U)) & S_BLOCK1], 26U) ^ RotL64(aWaterLaneC[((aIndex + 16160U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aEarthLaneA[((aIndex + 11032U)) & S_BLOCK1], 53U) ^ RotL64(aEarthLaneD[((S_BLOCK1 - aIndex + 13727U)) & S_BLOCK1], 11U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aTwistDomainWordIngress));
            //
            aCross = (RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 13573U)) & S_BLOCK1], 56U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 12104U)) & S_BLOCK1], 35U));
            aCross ^= (RotL64(pCrossLaneA[((S_BLOCK1 - aIndex + 9501U)) & S_BLOCK1], 13U) ^ RotL64(pCrossLaneC[((S_BLOCK1 - aIndex + 8973U)) & S_BLOCK1], 27U));
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 39U) + RotL64(aIngress, 52U)) ^ (RotL64(aPrevious, 23U) + RotL64(aCarry, 3U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (aWandererK + RotL64(aCross, 43U)) + 0x518F664CD11ACA5FULL;
            aOrbiterA = ((aWandererC + RotL64(aIngress, 19U)) + RotL64(aCarry, 39U)) + 0xE90DE9654EEC3C34ULL;
