            aOrbiterC = RotL64((aOrbiterC * 0x5AB84B73FA997F49ULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x6C987B6F1396D0F6ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xB9BABC5374B73D33ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xC926B90726978DA5ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x8DC6F07355B8DECFULL;
