            aOrbiterB = RotL64((aOrbiterB * 0xE96A26B305936F15ULL), 53U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x0FB1F28A4107BB9DULL) + aOUSaltC[((aIndex + 366U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x1BDF9A2537F39466ULL;
