            aWandererF = aWandererF + ((((RotL64(aScatter, 42U) + aOrbiterE) + RotL64(aOrbiterJ, 28U)) + RotL64(aCarry, 43U)) + aWUSaltG[(((511U - aIndex) + 460U)) & S_SALT1]);
